//! Zero-cost schema markers: tables, columns, and their relational contracts.
//!
//! Tables and columns are represented as zero-sized types. Every column is
//! statically tied to its owning table through [`Column::Table`], which lets the
//! compiler reject expressions that mix columns from unrelated tables at the
//! call site.

/// A table of the database schema, represented as a zero-sized marker type.
///
/// Implementations are usually generated by the [`table!`](crate::table) macro.
pub trait Table {
    /// The SQL identifier of the table, known at compile time.
    const NAME: &'static str;
}

/// A column of a database [`Table`], represented as a zero-sized marker type.
pub trait Column {
    /// The table this column belongs to.
    type Table: Table;

    /// The Rust type used to represent this column's values.
    type RustType;

    /// The SQL identifier of the column, known at compile time.
    const NAME: &'static str;
}

/// Statically asserts that a [`Column`] belongs to the table `T`.
///
/// The trait is satisfied exactly for the table declared as
/// [`Column::Table`], so using a column with a foreign table fails to compile
/// with a short, actionable diagnostic.
#[diagnostic::on_unimplemented(
    message = "column `{Self}` does not belong to table `{T}`",
    label = "column `{Self}` cannot be used where a column of `{T}` is required",
    note = "a column may only be used with the table declared by its `Column::Table` associated type"
)]
pub trait ColumnBelongsTo<T: Table> {}

impl<C: Column> ColumnBelongsTo<C::Table> for C {}

/// Position marker used to disambiguate table membership in composite scopes.
///
/// Lone tables use position 0 ([`At<0>`]), while composite scopes such as `(T1, T2)`
/// assign positions `At<1>`, `At<2>`, etc. to each member.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct At<const N: usize>;

/// Statically asserts that the [`Table`] `T` is part of the query scope.
///
/// Expressions may only reference tables that were added to the query, and every
/// table is trivially in scope of itself. Composite scopes represented as tuples
/// contain each of their member tables at distinct positions.
///
/// ```compile_fail
/// use rurqe_core::schema::{Table, TableInScope};
///
/// rurqe_core::table! {
///     User => "users" { UserId => "id": i64, }
///     Order => "orders" { OrderId => "id": i64, }
/// }
///
/// fn require_in_scope<T: Table, S: TableInScope<T, P>, P>() {}
///
/// // Fails to compile because `Order` is not in scope of `User`:
/// require_in_scope::<Order, User, _>();
/// ```
#[diagnostic::on_unimplemented(
    message = "table `{T}` is not part of this query's scope",
    label = "add `{T}` to the query before referencing its columns",
    note = "only tables introduced into the query scope can be used by its expressions"
)]
pub trait TableInScope<T: Table, P = At<0>> {}

impl<T: Table> TableInScope<T, At<0>> for T {}

macro_rules! impl_tuple_scope {
    ($(($elem:ident, $pos:expr) in ($($member:ident),+);)+) => {
        $(
            impl<$($member: Table),+> TableInScope<$elem, At<$pos>> for ($($member,)+) {}
        )+
    };
}

impl_tuple_scope! {
    (T1, 1) in (T1);

    (T1, 1) in (T1, T2);
    (T2, 2) in (T1, T2);

    (T1, 1) in (T1, T2, T3);
    (T2, 2) in (T1, T2, T3);
    (T3, 3) in (T1, T2, T3);

    (T1, 1) in (T1, T2, T3, T4);
    (T2, 2) in (T1, T2, T3, T4);
    (T3, 3) in (T1, T2, T3, T4);
    (T4, 4) in (T1, T2, T3, T4);

    (T1, 1) in (T1, T2, T3, T4, T5);
    (T2, 2) in (T1, T2, T3, T4, T5);
    (T3, 3) in (T1, T2, T3, T4, T5);
    (T4, 4) in (T1, T2, T3, T4, T5);
    (T5, 5) in (T1, T2, T3, T4, T5);

    (T1, 1) in (T1, T2, T3, T4, T5, T6);
    (T2, 2) in (T1, T2, T3, T4, T5, T6);
    (T3, 3) in (T1, T2, T3, T4, T5, T6);
    (T4, 4) in (T1, T2, T3, T4, T5, T6);
    (T5, 5) in (T1, T2, T3, T4, T5, T6);
    (T6, 6) in (T1, T2, T3, T4, T5, T6);

    (T1, 1) in (T1, T2, T3, T4, T5, T6, T7);
    (T2, 2) in (T1, T2, T3, T4, T5, T6, T7);
    (T3, 3) in (T1, T2, T3, T4, T5, T6, T7);
    (T4, 4) in (T1, T2, T3, T4, T5, T6, T7);
    (T5, 5) in (T1, T2, T3, T4, T5, T6, T7);
    (T6, 6) in (T1, T2, T3, T4, T5, T6, T7);
    (T7, 7) in (T1, T2, T3, T4, T5, T6, T7);

    (T1, 1) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T2, 2) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T3, 3) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T4, 4) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T5, 5) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T6, 6) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T7, 7) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T8, 8) in (T1, T2, T3, T4, T5, T6, T7, T8);
}

/// Statically asserts that `T` denotes a valid expression scope.
///
/// A scope is the set of relations an expression may reference: a lone table
/// ([`Table`]), a tuple of tables, or a joined query scope such as
/// [`Joined`](crate::query::Joined) and
/// [`LeftJoined`](crate::query::LeftJoined). The marker keeps expression
/// builders honest across joins without pinning them to one concrete scope
/// representation.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is not a valid expression scope",
    label = "expressions may only reference tables, table tuples, or joined scopes",
    note = "build expressions against a table, a tuple of tables, or a `Joined` / `LeftJoined` scope"
)]
pub trait ExprScope {}

impl<T: Table> ExprScope for T {}

macro_rules! impl_tuple_expr_scope {
    ($($member:ident),+) => {
        impl<$($member: Table),+> ExprScope for ($($member,)+) {}
    };
}

impl_tuple_expr_scope!(T1);

impl_tuple_expr_scope!(T1, T2);

impl_tuple_expr_scope!(T1, T2, T3);

impl_tuple_expr_scope!(T1, T2, T3, T4);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6, T7);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6, T7, T8);

/// Declares a table marker type together with its column marker types.
///
/// Each column links back to the table through [`Column::Table`] and carries its
/// Rust value type through [`Column::RustType`]:
///
/// ```
/// rurqe_core::table! {
///     /// The `users` table.
///     User => "users" {
///         UserId => "id": i64,
///         UserEmail => "email": String,
///     }
/// }
///
/// use rurqe_core::schema::{Column, Table};
///
/// assert_eq!(User::NAME, "users");
/// assert_eq!(UserEmail::NAME, "email");
/// assert_eq!(<<UserEmail as Column>::Table as Table>::NAME, "users");
/// ```
#[macro_export]
macro_rules! table {
    (
        $(#[$table_meta:meta])*
        $table:ident => $table_name:literal {
            $(
                $(#[$column_meta:meta])*
                $column:ident => $column_name:literal : $rust_type:ty,
            )*
        }
    ) => {
        $(#[$table_meta])*
        #[allow(dead_code)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub struct $table;

        impl $crate::schema::Table for $table {
            const NAME: &'static str = $table_name;
        }

        $(
            $(#[$column_meta])*
            #[allow(dead_code)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
            pub struct $column;

            impl $crate::schema::Column for $column {
                type Table = $table;
                type RustType = $rust_type;

                const NAME: &'static str = $column_name;
            }
        )*
    };
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::table! {
        User => "users" {
            UserId => "id": i64,
            UserEmail => "email": String,
        }
    }

    #[test]
    fn names_are_static_strings() {
        assert_eq!(User::NAME, "users");
        assert_eq!(UserId::NAME, "id");
        assert_eq!(UserEmail::NAME, "email");
    }

    #[test]
    fn column_links_to_its_table_and_rust_type() {
        assert_eq!(<<UserId as Column>::Table as Table>::NAME, "users");

        fn takes_rust_type<C: Column<RustType = String>>() {}
        takes_rust_type::<UserEmail>();
    }

    #[test]
    fn column_belongs_to_its_own_table() {
        fn assert_belongs<C: Column + ColumnBelongsTo<T>, T: Table>() {}

        assert_belongs::<UserId, User>();
        assert_belongs::<UserEmail, User>();
    }

    #[test]
    fn table_is_in_its_own_scope() {
        fn assert_in_scope<T: Table + TableInScope<T>>() {}

        assert_in_scope::<User>();
    }

    crate::table! {
        Order => "orders" {
            OrderId => "id": i64,
            OrderUserId => "user_id": i64,
        }
    }

    #[test]
    fn composite_scope_contains_all_member_tables() {
        fn assert_in_scope<T: Table, S: TableInScope<T, P>, P>() {}

        assert_in_scope::<User, (User, Order), _>();
        assert_in_scope::<Order, (User, Order), _>();
        assert_in_scope::<User, (Order, User), _>();
        assert_in_scope::<Order, (Order, User), _>();
    }

    #[test]
    fn composite_scope_supports_self_joins() {
        fn assert_in_scope<T: Table, S: TableInScope<T, P>, P>() {}

        assert_in_scope::<User, (User, User), At<1>>();
        assert_in_scope::<User, (User, User), At<2>>();
    }
}
